                show: true,
                formatter: '{b}: {d}%',
                color: '#333',
                fontWeight: 'bold'
              },
              labelLine: {
                show: true,
                length: 10,
                length2: 15
              },
              emphasis: {
                label: {
                  show: true,
                  fontSize: '18',
                  fontWeight: 'bold'
                }
              },
              data: [{
                value: data.male_count,
                name: '男',
                itemStyle: {
                  color: '#5470C6'
                }
              }, {
                value: data.female_count,
                name: '女',
                itemStyle: {
                  color: '#EE6666'
                }
              }]
            }]
          };
          genderChartInstance.setOption(option);
